const fs = require('fs');
const DIR = '/files/config';
let user = { selections: {}, ubicacion_laboral: '' };
let modules = {};
try { user = JSON.parse(fs.readFileSync(DIR + '/user_profile.json', 'utf8')); } catch (e) {}
try { modules = JSON.parse(fs.readFileSync(DIR + '/modules.json', 'utf8')); } catch (e) {}

const pick = (dim) => Array.isArray(user.selections && user.selections[dim]) ? user.selections[dim] : [];
const find = (list, id) => (list || []).find((o) => o && o.id === id);

const idiomaId = pick('idioma')[0] || 'espanol';
const idioma = (find(modules.idioma, idiomaId) && find(modules.idioma, idiomaId).valores.codigo) || 'es';

const kwFormacion = pick('formacion').flatMap((id) => {
  const m = find(modules.formacion, id);
  return (m && m.valores && m.valores.keywords_linkedin) || [];
});
const kwSector = pick('sector_interes').flatMap((id) => {
  const m = find(modules.sector_interes, id);
  return (m && m.valores && m.valores.industrias) || [];
});
const keywords = [...new Set([...kwFormacion, ...kwSector])].slice(0, 8).join(',');

const formacionNombre = (find(modules.formacion, pick('formacion')[0]) || {}).nombre || 'ingeniería';
const objetivoNombre = (find(modules.objetivo_profesional, pick('objetivo_profesional')[0]) || {}).nombre || 'primer empleo';
const location = user.ubicacion_laboral || 'Barcelona';

return [{ json: { profile: {
  idioma,
  keywords: keywords || 'Engineer,Analyst,Operations',
  location,
  perfil_texto: 'Profesional de ' + formacionNombre + ' con objetivo: ' + objetivoNombre + '. Ubicación: ' + location + '.',
} } }];

// El scraper devuelve { ok, source, jobs: [...] }. Un item por oferta.
const r = $input.first().json || {};
const jobs = Array.isArray(r.jobs) ? r.jobs : [];
const source = r.source || 'desconocido';
if (jobs.length === 0) return [{ json: { __sinOfertas: true, motivo: 'el scraper no devolvió ofertas', source } }];
return jobs.map((j) => ({ json: { ...j, source } }));

// Filtra ofertas claramente fuera de objetivo (roles y ubicación).
const INCLUDE = ['engineer','engineering','analyst','operations','supply chain','logistics','project','program','product','data','software','developer','consultant','consulting','strategy','automation','manufacturing','industrial','process','planning','transformation','innovation','graduate','junior','trainee','intern','associate','ai','machine learning','cloud','devops','backend','full stack'];
const EXCLUDE = ['sales representative','account executive','call center','teleoperador','camarero','waiter','kitchen','limpieza','cleaner','conductor','driver','repartidor','beca no remunerada','unpaid'];

const pass = [];
for (const item of $input.all()) {
  const j = item.json;
  if (j.__sinOfertas) { pass.push({ json: j }); continue; }
  const hay = ((j.title || '') + ' ' + (j.descriptionSnippet || '')).toLowerCase();
  if (EXCLUDE.some((w) => hay.includes(w))) continue;
  if (!INCLUDE.some((w) => hay.includes(w))) continue;
  pass.push({ json: j, pairedItem: item.pairedItem });
}
return pass;

const store = $getWorkflowStaticData('global');
const seen = store.jobsSeen || {};
const now = Date.now();
const TTL = 21 * 24 * 60 * 60 * 1000;
for (const k of Object.keys(seen)) { if (now - seen[k] > TTL) delete seen[k]; }

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (j.__sinOfertas) { out.push({ json: j }); continue; }
  const key = (j.link || (j.title + '|' + j.company)).toLowerCase().trim();
  if (!key || seen[key]) continue;
  seen[key] = now;
  out.push({ json: j, pairedItem: item.pairedItem });
}
store.jobsSeen = seen;
return out;

// Puntuación determinista 0-100.
const ROLE_SCORES = { 'aerospace':30,'aeroespacial':30,'space':25,'espacio':25,'artificial intelligence':25,'inteligencia artificial':25,'machine learning':22,'automation':20,'digital transformation':20,'supply chain':18,'industrial engineer':18,'project manager':16,'project engineer':16,'program manager':15,'data':15,'operations':14,'business analyst':14,'consultant':13,'strategy':13,'software':12,'manufacturing':12,'logistics':11,'planning':11,'engineering':9,'engineer':7 };
const PRIORITY = ['airbus','boeing','indra','thales','gmv','sener','esa','nasa','spacex','siemens','honeywell','accenture','capgemini','mckinsey','bcg','deloitte','pwc','kpmg','ey','amazon','google','microsoft','sap','seat','nvidia','ibm'];
const JUNIOR = ['junior','graduate','trainee','intern','becario','entry level','associate','young talent'];

function scoreOne(j) {
  const hay = ((j.title || '') + ' ' + (j.descriptionSnippet || '')).toLowerCase();
  const company = (j.company || '').toLowerCase();
  let s = 5;
  for (const [k, v] of Object.entries(ROLE_SCORES)) if (hay.includes(k)) s += v;
  if (PRIORITY.some((c) => company.includes(c))) s += 20;
  if (JUNIOR.some((k) => hay.includes(k))) s += 10;
  if (j.postedAt) {
    const days = (Date.now() - new Date(j.postedAt).getTime()) / 86400000;
    if (days <= 3) s += 8; else if (days <= 7) s += 4;
  }
  return Math.max(0, Math.min(100, Math.round(s)));
}

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (j.__sinOfertas) { out.push({ json: j }); continue; }
  out.push({ json: { ...j, score: scoreOne(j) }, pairedItem: item.pairedItem });
}
return out;

const MIN_SCORE = 15;
const MAX = 3;
const rows = $input.all().map((i) => i.json).filter((j) => !j.__sinOfertas);
const top = rows.filter((j) => (j.score || 0) >= MIN_SCORE).sort((a, b) => (b.score || 0) - (a.score || 0)).slice(0, MAX);
if (top.length === 0) {
  return [{ json: { __sinOfertas: true, motivo: 'ninguna oferta superó el umbral', evaluadas: rows.length } }];
}
return top.map((j) => ({ json: j }));

