let g = {};
try {
  const raw = ($json.candidates && $json.candidates[0] && $json.candidates[0].content
    && $json.candidates[0].content.parts && $json.candidates[0].content.parts[0]
    && $json.candidates[0].content.parts[0].text) || '{}';
  g = JSON.parse(raw);
} catch (e) { g = {}; }

let job = {};
try { job = $('Seleccionar TOP 3').item.json; } catch (e) { job = {}; }

const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const resumen = g.resumen || (job.descriptionSnippet || '').slice(0, 180) || 'Sin descripción.';

return { json: {
  title: esc(job.title || 'Oferta'),
  company: esc(job.company || '—'),
  location: esc(job.location || '—'),
  score: job.score || 0,
  link: job.link || '',
  source: job.source || '',
  resumen: esc(resumen),
  motivo_fit: esc(g.motivo_fit || ''),
} };
